#include <bits/stdc++.h>
using namespace std;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    while (cin >> n >> m && (n || m))
    {
        vector<int> ok(1 << m);
        // 预处理合法单行状态
        for (int sta = 0; sta < (1 << m); sta++)
        {
            int cnt = 0;
            bool good = true;
            for (int i = 0; i < m; i++)
            {
                if (sta >> i & 1)
                {
                    if (cnt & 1)
                    {
                        good = false;
                        break;
                    }
                    cnt = 0;
                }
                else
                {
                    cnt++;
                }
            }
            if (cnt & 1) good = false;
            ok[sta] = good;
        }

        // 预处理合法状态转移
        vector<vector<int>> trans(1 << m);
        for (int a = 0; a < (1 << m); a++)
        {
            for (int b = 0; b < (1 << m); b++)
            {
                if ((a & b) == 0 && ok[a | b])
                {
                    trans[a].push_back(b);
                }
            }
        }

        vector<long long> dp(1 << m), ndp(1 << m);
        dp[0] = 1;
        // 逐行DP
        for (int i = 0; i < n; i++)
        {
            fill(ndp.begin(), ndp.end(), 0);
            for (int a = 0; a < (1 << m); a++)
            {
                if (!dp[a]) continue;
                for (int b : trans[a])
                {
                    ndp[b] += dp[a];
                }
            }
            dp.swap(ndp);
        }
        cout << dp[0] << '\n';
    }
    return 0;
}
